    private static final AtomicBoolean finished=new AtomicBoolean();
    private static final Map<String,Object> report=new LinkedHashMap<>();
    private static final List<Object> registryChecks=new ArrayList<>(),kills=new ArrayList<>(),attacks=new ArrayList<>(),events=new ArrayList<>();
    private static final List<net.farmingtales.ftboss.util.BossRelicRules.Kind> KINDS=List.of(net.farmingtales.ftboss.util.BossRelicRules.Kind.values());
    private static final Map<net.farmingtales.ftboss.util.BossRelicRules.Kind,String> MATERIAL_IDS=Map.ofEntries(Map.entry(KINDS.get(0),"frost_material"),Map.entry(KINDS.get(1),"butcher_material"),Map.entry(KINDS.get(2),"tea_material"),Map.entry(KINDS.get(3),"wine_material"),Map.entry(KINDS.get(4),"cheese_material"),Map.entry(KINDS.get(5),"capacitor_material"),Map.entry(KINDS.get(6),"spore_material"),Map.entry(KINDS.get(7),"apple_material"),Map.entry(KINDS.get(8),"shepherd_material"),Map.entry(KINDS.get(9),"tide_material"));
    private static ServerPlayer player;
    private static ServerLevel level;
    private static LivingEntity primary;
    private static net.farmingtales.ftboss.util.BossRelicRules.Kind currentKind;
    private static final Set<UUID> beforeSummon=new HashSet<>();
    private static boolean worldRequested,clientReady,observing;
    private static int checks,clientTicks,serverTicks,kindIndex,phase,protectedHits,attackEvents,preEvents,postEvents,deathEvents,naturalEntityTicks,currentPositiveHits;
